out = os.path.join(os.path.dirname(__file__), '..', 'test-cases')
rows = []
summary = []
for key, (title, cases) in FEATURES.items():
    lines = [f"# {title} — test cases\n", "| ID | Type | Objective | Preconditions | Steps | Expected result | Priority | Severity | Automation |", "|---|---|---|---|---|---|---|---|---|"]
    for i, c in enumerate(cases, 1):
        t, obj, pre, steps, exp, pri, sev, auto = c
        tid = f"TC-{key}-{i:02d}"
        lines.append(f"| {tid} | {t} | {obj} | {pre} | {steps} | {exp} | {pri} | {sev} | {auto} |")
        rows.append([tid, title, t, obj, pre, steps, exp, pri, sev, auto])
    open(os.path.join(out, f"TC-{key}.md"), "w").write("\n".join(lines) + "\n")
    summary.append((key, title, len(cases)))
with open(os.path.join(out, "test-cases.csv"), "w", newline="") as f:
    w = csv.writer(f); w.writerow(["id","feature","type","objective","preconditions","steps","expected","priority","severity","automation"]); w.writerows(rows)
auto = sum(1 for r in rows if r[9].startswith("✅")); elig = sum(1 for r in rows if r[9].startswith("🟡"))
print(summary, len(rows), "automated", auto, "eligible", elig)
from collections import Counter
print(Counter(r[2] for r in rows), Counter(r[7] for r in rows))
